package com.yeyamo_mobile.api.feed_service.infrastructure.messaging;import org.apache.kafka.common.TopicPartition;import org.springframework.context.annotation.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.*;import org.springframework.util.backoff.FixedBackOff;@Configuration public class KafkaErrorConfig{@Bean DefaultErrorHandler feedErrorHandler(KafkaTemplate<String,String>k){return new DefaultErrorHandler(new DeadLetterPublishingRecoverer(k,(r,e)->new TopicPartition(r.topic()+".DLT",r.partition())),new FixedBackOff(1000,3));}}
